#[test] fn inspect(){
for entry in std::fs::read_dir("/tmp/fvid-lossy-sweep").unwrap() { let path=entry.unwrap().path(); if path.extension().and_then(|v|v.to_str())!=Some("obu"){continue;} let name=path; print!("{} ",name.file_name().unwrap().to_str().unwrap()); let bytes=std::fs::read(name).unwrap();let os:Vec<_>=fvid::codec::av1::Obus::new(&bytes).map(Result::unwrap).collect();let s=fvid::codec::av1_sequence::Sequence::parse(os.iter().find(|o|o.kind==1).unwrap().payload).unwrap();let o=os.iter().find(|o|o.kind==6).unwrap();let h=fvid::codec::av1_frame::Header::parse_intra(&s,o.payload,0,0).unwrap();println!("levels {:?}, Q {}",h.filter.levels,h.quant.base);let mut d=fvid::codec::av1_decoder::Decoder::new(16<<20);let f=d.decode_packet(&bytes).unwrap();println!("palettes {:?}, residuals {:?}",f[0].picture.palette_counts,f[0].picture.palette_residual_blocks);}}
